architecture.h4_f:
msg = CBOR{v:1, text, reply_to, send_at}
ct = AES-GCM-256-Enkriptatzea (k, nonce, msg, aad=gela_id)
POST /api/rooms/{id}/messages {zifratuaren testua: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, text, reply_to?, thread_id?, aipamenak?, bidali_at}
ct = AES-GCM-256-Enkriptatzea (gela_gakoa, nonce, pt, aad=hex (gela_id))
haria = CBOR{
  v: 1,
  testu zifratua: hex(ct), // luzera aldakorra
  nonce: hex (12 B),
  igorle_pseudo: hex (16 B),
  bidali_at: unix_ms
}

cryptoWire.h5_f:
kanpoaldea = CBOR{
  iturburu_nodoa: hex32,
  xede_erabiltzailea: int64,
  inner_ciphertext: byte,
  inner_nonce: byte,
  bidali_at: unix_ms
}
sig = Ed25519-Sign (iturburu_priv, kanpoaldea)
POST /federation/deliver { gutun-azala: kanpoaldea, sig: hex64 }

auth.h1_f:
POST /api/authentication/register
  { erabiltzaile-izena, pasahitza, x25519_public_key, display_name, telefonoa?, posta elektronikoa?, avatar_emoji }

201. erantzuna Sortua:
  { access_token, refresh_token, user_id, username, ... }

auth.h3_f:
access_token karga:
  { azpi: user_id, jti: device_id, typ: "sarbidea", exp: orain + 15min }
refresh_token karga:
  { azpi: user_id, jti: device_id, typ: "freskatu", exp: orain + 30d }

HS256 - .env-tik nodoaren 64 byteko sekretuarekin sinatua

auth.h4_f:
register_begin(): erronka = rand(32)
                    aukerak = { rp.id, user.id, pubKeyCredParams, challenge }
                    itzultzeko aukerak

erregistratu_amaiera(ziurtagiria):
  egiaztatzea TPM / Secure Enclave root CA
  gorde {credential_id, public_key, counter: 0}

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: 128 biteko hex, ttl: 60 }
QR karga karga = { nonce, user_id, zerbitzaria: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → gailu berria erregistratu; JWT-ak itzuli ziren.

rooms.h6_f:
sender_pseudo = HMAC-SHA256 (gela_pseudo_salt, sender_id)[:16] // 32 hex
zifratu-testua = AES-GCM-Enkriptatzea (gela_gakoa, nonce, CBOR_payload, aad=gela_id)

Fan-out markoa: { type:"m", room, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {fitxategi-izena, tamaina, zati_tamaina_iradokizuna}
            ← {upload_id, chunk_size}
zatia PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← 204
amaitu POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {fitxategi_id, url}
TTL amaitu gabe dagoenean: 24 h

presence.h1_f:
bezeroa: lehenengo tekla sakatzean → bidali {mota:"t", egoera:"hasi"}
         ez da gehiago bidaltzen 3 s egoera aldatzen ez bada
         Azken tekla sakatu ondoren 10 s → bidali {mota:"t", egoera:"gelditu"}
hargailua: auto-gelditzea azken "hasi"-tik 10 segundora "gelditzeko" iristen ez bada

calls.h1_f:
POST /api/calls/{room_id}/hasi {bideoa, audioa} → call_id
WS emititu {type:"c", kind:"gonbidatu", call_id}
WS emititu {mota:"c", mota: "eskaintza", sdp}
WS emititu {mota:"c", mota: "erantzuna", sdp}
WS emititu {mota:"c", mota:"hautagaia", izotza} × N
POST /api/calls/{call_id}/end

federation.h2_f:
gutun-azala = {
  iturburu_nodoa: hex32,
  xede_erabiltzailea: int64,
  inner_ciphertext: byte,
  inner_nonce: byte,
  sent_at : unix_ms,
}
sig = Ed25519Sign (iturburua_priv, CBOR (kartazala))
POST /federation/deliver { gutun-azal, sig }

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {izena: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(public_key_from_HTTPS_record)
DGA: domeinua(t) = oinarri32( SHA256(hazia ∥ YYYY-MM-DD) )[:16] + ".adibidea"

push.h4_f:
iOS NSE: didReceive (eskaera) { deszifratu (request.content.userInfo) }
Android FCM: onMessageReceived(remoteMessage) { desencrypt(remoteMessage.data) }
Web SW: self.addEventListener('push', e => deszifratu (e.data))

controller.h2_f:
tresna = seinale_tresna
sarrera = iturburu-zuhaitza, keys/release.key
manifestua = {
  bertsioa: "0.1.0",
  eraiki_at: unix_ms,
  fitxategiak: [{bidea, sha256, tamaina}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(manifestua))
irteera = INTEGRITY.sig.json = {manifestua, sinatuta: pub_hex, sig: sig_hex}

bots.h1_f:
sortu: POST /api/bots {erabiltzaile-izena, bistaratzeko_izena, kodea}
          → {bot_id, token, pubkey}
Exekutatu: prozesuan (korrutina nodoaren barruan)
      OR kanpoko (inkesta luzea /api/bots/{id}/eguneratzeak, token-autentifikazioa)
mezua: {testua, sinadura: Ed25519-Sign(bot_priv, canonical_msg)}

bots.h2_f:
/hasi {
  igorri "Ongi etorri, {ctx.first_name}"
}
on /gehitu <elementua> {
  egoera.zerrenda = (egoera.zerrenda edo []) + [ctx.args.item]
  igorri "Gehituta: {ctx.args.item}"
}

debugging.h2_f:
tasatu histogramak (ibilbide bakoitzeko + metodoa):
  vortex_http_requests_total{ibilbidea,metodoa,egoera}
  vortex_http_request_duration_seconds_bucket{ibilbidea,metodoa,le}

websocket neurgailuak:
  vortex_ws_connections{nodoa}
  vortex_ws_fanout_queue_depth{room,user}

kontagailu pertsonalizatuak:
  vortex_messages_sent_total{room_type}
  vortex_calls_started_total{kind}

