GET /v1/integrity → {status, signed_by, bated, desparted, …}
GET /v1/health → {egoera, bertsioa, pubkey, estatistikak}
GET /v1/sarrerak → [{protokoloa, url}, …]
GET /v1/ispiluak → [controller_url, …]

fcm.h1_f:
POST https://fcm.googleapis.com/v1/projects/<project>/messages:send
Baimena: Bearer <oauth2_token>
Gorputza: {message: {token: <device>, data: {...sealed...}, android: {collapse_key}}}

federation.h1_f:
envelope = {source_node, target_user, inner_ct, inner_nonce, send_at}
sig = Ed25519-Sign (iturburua_priv, CBOR (kartazala))
POST /federation/deliver {gutun-azal, sig}
B-k egiaztatzen du: federazioen aurka sinatu[source_node].pubkey

fts5.h1_f:
CREATE VIRTUAL TABLE messages_fts USING fts5(
  edukia, -- tokenizatutako zutabea
  room_id UNINDEXED,
  tokenize = 'unicode61 remove_diacritics 2'
);
kontsulta: SELECT rowid FROM messages_fts WHERE edukia MATCH 'foo'

